return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'skr','project-id-version'=>'Babilim 2.2.1','pot-creation-date'=>'2026-11-09T07:54:35+00:00','po-revision-date'=>'2026-11-09T07:54:35+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'جݙاں تُساں Babilim چالو کرو دبیندے ہو تاں بھیڄیا ویندا ہے، تے جے سائٹ کوں نواں رجسٹر کرݨ پوۓ تاں وی: تہاݙی سائٹ دا URL، WordPress، PHP تے Babilim دے ورژن، تہاݙی سائٹ دی زبان تے اس تے ورتیاں ون٘ڄݨ والیاں زباناں، تے اس سائٹ واسطے بݨائی گئی اک عوامی کنجی۔','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'ہر جانچ تے بھیڄیا ویندا ہے: انسٹال کیتے ہوئے پلگ اِن تے تھیماں دی لسٹ، جنھاں واسطے کوئی Babilim ترجمہ انسٹال ہے اوندی حالت، ورتیاں ون٘ڄݨ والیاں زباناں، تے مختصر تشخیصی کوڈ۔','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'ہر درخواست وچ تہاݙی سائٹ دا URL شامل ہوندا ہے، تے جݙاں وی سروس کوں لوڑ ہووے سائٹ دا رسائی ٹوکن وی شامل کیتا ویندا ہے۔','What Babilim sends to the service'=>'Babilim سروس کوں کیا بھیڄدا ہے','Your site\'s URL'=>'تہاݙی سائٹ دا URL','WordPress version'=>'WordPress ورژن','PHP version'=>'PHP ورژن','Babilim version'=>'Babilim ورژن','Your site\'s language'=>'تہاݙی سائٹ دی زبان','Languages in use on your site'=>'تہاݙی سائٹ تے ورتیاں ون٘ڄݨ والیاں زباناں','A public key for this site'=>'ایں سائٹ واسطے اک عوامی کنجی','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'ایں سائٹ واسطے بݨائی گئی اک عوامی کنجی، جیڑھی ایہ ثابت کرݨ واسطے ورتی ویندی ہے جو درخواستاں سچی مچی ایں سائٹ توں آندیاں ہن۔ صرف عوامی حصہ بھیڄیا ویندا ہے؛ نجی حصہ تہاݙی سائٹ تے ای رہندا ہے۔','Installed plugins and themes'=>'انسٹال کیتے ہوئے پلگ اِن تے تھیم','Source files (only if you confirm an upload)'=>'سورس فائلاں (صرف جے تُساں اپ لوڈ دی تصدیق کرو)','Diagnostic codes'=>'تشخیصی کوڈ','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'20 تک مختصر تشخیصی کوڈ (مثال دے طور تے، ترجمے دی اوہ فائل جیڑھی اپݨی جانچ وچ ناکام تھئی)، ہر اک نال پلگ اِن یا تھیم، زبان تے او ویلا جݙاں ایہ تھیا۔ ایندے وچ تہاݙی سائٹ دا کوئی متن یا کوئی ترجمہ کیتا ہویا متن کݙاہیں شامل کائنی ہوندا۔','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'ایں نیٹ ورک تے %1$d سائٹ ایں طرح سیٹ ہے جو پلگ ان مٹاونْ تے اپݨی Babilim شناخت مٹا ݙیوے۔ پھر ایں سائٹ نال جڑیا ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدا؛ تُہاکوں %2$s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناخت رکھݨ کیتے منسوخ دباؤ، ایں سائٹ دیاں Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟' . "\0" . 'ایں نیٹ ورک تے %1$d سائٹاں ایں طرح سیٹ ہن جو پلگ ان مٹاونْ تے اپݨی Babilim شناخت مٹا ݙیون۔ پھر ایں سائٹاں نال جڑے ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدے؛ تُہاکوں %2$s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناختاں رکھݨ کیتے منسوخ دباؤ، ہر سائٹ دیاں Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s کرݨ دی کوئی گال کائنی۔','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s۔ زبان چݨو۔','%d failed'=>'%d ناکام' . "\0" . '%d ناکام','%d not yet tried'=>'%d دی ہݨ تک کوشش کائنی تھئی' . "\0" . '%d دی ہݨ تک کوشش کائنی تھئی','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d رپورٹ انتظار کر رہی ہے۔ "Always share" تے "Don\'t share" سارئیں تے لاگو تھیندے ہن۔' . "\0" . '%d رپورٹاں انتظار کر رہیاں ہن۔ "Always share" تے "Don\'t share" سارئیں تے لاگو تھیندے ہن۔','%d skipped'=>'%d چھوڑے ڳئے' . "\0" . '%d چھوڑے ڳئے','%d succeeded'=>'%d کامیاب' . "\0" . '%d کامیاب','%d to install'=>'%d انسٹال کرݨ کیتے' . "\0" . '%d انسٹال کرݨ کیتے','(a public key generated for this site)'=>'(اس سائٹ کیتے بݨائی گئی پبلک کی)','(detected)'=>'(پتہ لگیا)','(generic codes and coordinates only)'=>'(صرف عام کوڈ تے کوآرڈینیٹس)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s تے صفائی روک ݙتی گئی: %2$s۔ کجھ وی ڈیلیٹ کائنی کیتا گیا۔','A file in the component could not be read, so it was not packaged.'=>'کمپوننٹ دی اک فائل پڑھی نہیں جا سکی، ایں کِیتے اوکوں پیک نہیں کیتا گیا۔','A host that serves only one PHP request at a time cannot complete this step.'=>'جیڑھا ہوسٹ اکو ویلے صرف اکو PHP درخواست سنبھالیندا ہے، او ایہ مرحلہ مکمل نہیں کر سگدا۔','A part of the upload kept failing, so the upload was cancelled.'=>'اپ لوڈ دا اکو حصہ بار بار ناکام ریہا، اس کیتے اپ لوڈ منسوخ کر ݙتا گیا۔','A translation cannot be requested for that locale on this site right now.'=>'ایں لوکیل کیتے ایں سائٹ تے ہݨ ترجمے دی درخواست نہیں کیتی ونڄ سڳدی۔','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'ترجمہ انڈیکس دی لکھائی %1$s تے ݙوجھی درخواست نال ٹکرا گئی (%2$s) تے لاگو نئیں تھئی؛ سب توں نواں ورژن رکھیا ڳیا۔','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s تے ترجمہ انڈیکس دی لکھائی (%2$s) مکمل نئیں تھی سڳی تے لاگو نئیں تھئی (%3$s)۔','Account'=>'اکاؤنٹ','Add another language'=>'ہک ہور زبان شامل کرو','Advanced'=>'ایڈوانس','All'=>'سارے','All free-plan slots for this site are used'=>'اس سائیٹ واسطے مفت پلان دے سارے سلاٹ ورتے ون ہوئے ہن','All languages'=>'ساریاں زباناں','Already in WordPress core'=>'پہلے ای WordPress کور وچ موجود ہے','Already installed.'=>'پہلے توں انسٹال ہے۔','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'ہک ہور انسٹالیشن چل رہی ہے؛ تھوڑی دیر بعد دوبارہ کوشش کرو۔','Automatic installs'=>'آپوں آپ انسٹال','Automatic installs are now off; turn them on again in the settings if you want them.'=>'خودکار انسٹال ہݨ بند ہن؛ جے چاہو تاں ترتیباں وچ ولدا آن کر گھنو۔','Available'=>'دستیاب','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'دستیاب ترجمے اکو کلک نال انسٹال کیتے ونج سڳدے ہن تے گم شدہ ترجمیاں دی درخواست کیتی ونج سڳدی اے۔ جڈاں خودکار انسٹالیشناں چالو ہوون، تاں جہڑے ترجمے سروس تہاڈیاں منیجڈ زباناں واسطے دستیاب دسیندی اے اوہ روزانہ دو واری سنک دے دوران انسٹال تھی ویندے ہن۔','Available · %s'=>'دستیاب · %s','Babilim'=>'Babilim','Babilim adds translations for every language checked here.'=>'Babilim ہیٹھ نشان زد ہر زبان کِیتے ترجمے شامل کریندا ہے۔','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim ویب سائٹ توں باہر کوئی عارضی فولڈر تصدیق نہیں کر سڳیا، ایں لئی جزو دا پیکیج نہیں بنیا تے کجھ وی اپ لوڈ نہیں تھیا۔ wp-config.php وچ BABILIM_TEMP_DIR کوں ویب روٹ توں باہر لکھن جوڳے فولڈر دے طور تے طے کرو (مثال دے طور تے تہاڈی سائٹ دی پبلک ڈائریکٹری دے اندر نہیں، بلکہ اوندے نال دا فولڈر)، یا اپنے ہوسٹ کولوں منگو۔','Babilim could not finish checking this site.'=>'Babilim ایں سائٹ دی چیکنگ مکمل نہیں کر سکیا۔','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim چالو کرݨ مکمل نہیں کر سگیا (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ایں سائٹ دی تصدیق مکمل نہیں کر سڳیا (سروس واپس اتھاں تک نہیں پہنچ سڳی)۔ رجسٹریشن روکی ڳئی ہے۔','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ایں سائٹ دی تصدیق نہیں کر سکیا، اس کیتے تصدیق کامیاب تھیݨ تک کجھ ڈاؤن لوڈ یا انسٹال نہیں تھیسی۔','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ایس سائٹ دی تصدیق نہیں کر سگیا، ایں کیتے کجھ ڈاؤن لوڈ یا انسٹال نہیں کیتا ڳیا۔','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim ایس سائٹ دے اُنہاں پلگ اِنز تے تھیمز واسطے Babilim سروس کولھوں ترجمے گھندا ہے جنہاں دا تہاڈی زبان وچ کوئی ترجمہ کائنی، تے اُنہاں کوں نصب کریندا ہے جیڑھے تہاڈے سروس پلان وچ شامل ہِن۔','Babilim has not been enabled for this site yet.'=>'Babilim ہݨ تائیں ایں سائٹ کیتے فعال کائنی کیتا ڳیا۔','Babilim has not installed any translation for this language.'=>'Babilim ایں زبان کیتے کوئی ترجمہ انسٹال کائناں کیتا۔','Babilim hit an error. Share an error report?'=>'Babilim وچ ایرر آ ڳیا۔ ایرر رپورٹ شیئر کرو؟','Babilim installed %d translation automatically since your last visit.'=>'تہاݙی پچھلی وزٹ توں بعد Babilim نے %d ترجمہ خودکار طور تے انسٹال کیتا۔' . "\0" . 'تہاݙی پچھلی وزٹ توں بعد Babilim نے %d ترجمے خودکار طور تے انسٹال کیتے۔','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim بند ہے۔ ہور کجھ نہیں ٻھیجیا ویسی؛ پہلے توں انسٹال کیتے ہوئے ترجمے کم کریندے رہسن۔','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim فعال ہے: ایہ سائٹ تصدیق شدہ ہے تے %d کمپوننٹ لبھیا ڳیا۔' . "\0" . 'Babilim فعال ہے: ایہ سائٹ تصدیق شدہ ہے تے %d کمپوننٹ لبھے ڳئے۔','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim ایں سائٹ کوں چالو تے چیک کر رہیا ہے… (آخری کوشش: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim ایں سائٹ کوں چالو تے چیک کر رہیا ہے… ایں ورقے کوں ریلوڈ کرو یا شیڈول چیک مکمل تھیوݨ دا انتظار کرو۔','Babilim is not enabled.'=>'Babilim فعال کائنی۔','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim ایں طرح سیٹ ہے جو پلگ ان مٹاونْ تے ایں سائٹ دی شناخت مٹا ݙیوے۔ پھر ایں سائٹ نال جڑیا ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدا؛ تُہاکوں %s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناخت رکھݨ کیتے منسوخ دباؤ، Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim دا ایں مرحلے کیتے وقت مک گیا تے اگلی چیک تے جاری رکھسی۔','Babilim settings'=>'Babilim ترتیباں','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim سنک سروس ولوں عارضی طور تے رُکی ہوئی ہے (ریٹ لمٹ)؛ اے %s توں بعد ول کوشش کرسی۔','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'اس اپ لوڈ دے انتظار دوران Babilim اپ ڈیٹ تھی گیا۔ پرانا پیکیج رد کر ݙتا گیا ہے؛ مہربانی کر کے اپ لوڈ دی دوبارہ تصدیق کرو۔','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (ورژن %2$s) دیاں اے فائلاں اپ لوڈ کریسی: ہر .php تے .js فائل، ہر block.json فائل، تے اینکوں دے مین فولڈر وچ readme.txt، readme.md، style.css تے theme.json۔ اے او متن لبھن لئی تے پلگ ان یا تھیم دی شناخت کرن لئی ورتیاں ویندیاں ہن جنکوں ترجمے دی لوڑ ہے۔','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest مہیا نہیں اے: %s','Back'=>'واپس','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'کیا تُساں ایں ڈومین کِیتے پہلے لائسنس خریدیا ہئی؟ چیک آؤٹ ویلے ملیا ہویا بحالی کوڈ درج کرو۔','Broken placeholder'=>'ٹُٹا ہویا پلیس ہولڈر','Build'=>'بلڈ','Built'=>'تیار کیتا ڳیا','Bulk actions apply only to the selected language of each selected component.'=>'بلک ایکشنز ہر چݨے ہوئے کمپوننٹ دی صرف چݨی ہوئی زبان تے لاگو تھیندے ہن۔','Bulk actions apply to every matching language of each selected component.'=>'بلک ایکشنز ہر چݨے ہوئے کمپوننٹ دی ہر مطابق زبان تے لاگو تھیندے ہن۔','Bulk download:'=>'کٹھا ڈاؤن لوڈ:','Bulk request:'=>'کٹھی درخواست:','Bulk update:'=>'کٹھی اپ ڈیٹ:','Bundled with the plugin'=>'پلگ اِن نال شامل','Bundled with the theme'=>'تھیم نال شامل','By clicking Enable, you agree to send the information listed above to Babilim.'=>'چالو کرو تے کلک کرݨ نال تساں اُتے ݙتی ہوئی معلومات Babilim کوں ٻھیجݨ تے راضی تھیندے او۔','By continuing you confirm that you have the right to upload this component.'=>'جاری رکھݨ نال تusاں تصدیق کریندے ہو جو ایہ کمپوننٹ اپ لوڈ کرݨ دا تہاڈے کول حق ہے۔','Cancel'=>'منسوخ کرو','Category'=>'زمرہ','Check again'=>'ولدا چیک کرو','Check again now'=>'ہݨ ولدا چیک کرو','Checkout is not available for this site right now.'=>'ایں سائٹ کیتے چیک آؤٹ ہݨ دستیاب نہیں ہے۔','Choose'=>'چݨو','Choose a category…'=>'زمرہ چݨو…','Choose a language'=>'زبان چݨو','Choose a language…'=>'زبان چُݨو…','Clear filters'=>'فلٹر صاف کرو','Close'=>'بند کرو','Component'=>'کمپوننٹ','Confirm'=>'تصدیق کرو','Conflicting keys'=>'متصادم کیز','Continue'=>'جاری رکھو','Continue next batch (%d left)'=>'اڳلی کھیپ جاری رکھو (%d باقی)','Continuing…'=>'جاری ہے…','Could not back up %s before replacing it.'=>'%s کوں بدلݨ کنوں پہلے بیک اپ نہیں کر سڳے۔','Could not create the package archive.'=>'پیکیج آرکائیو نہیں بݨ سکیا۔','Could not determine active components; the existing merged index was left unchanged.'=>'فعال جزو دا پتہ کائنی لگ سگیا؛ موجودہ ضم شدہ انڈیکس کوں نہیں بدلیا گیا۔','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'انسٹال کیتے ہوئے پلگ ان/تھیم دا پتہ کائنی لگ سگیا؛ صفائی چھوڑ دتی گئی، کجھ وی کائنی مٹایا گیا۔','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'سروس کنوں WordPress.org دی پوری لوکیل فہرست لوڈ کائنی تھی سڳی، ایں کیتے ہݨ کوئی ہور زبان شامل کائنی کیتی ونڄ سڳدی۔','Could not move %s into place.'=>'%s کوں اپݨی جاہ تے نہیں رکھ سڳے۔','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' دی ضم شدہ فہرست مقررہ جاء تے منتقل نئیں کیتی ونڄ سگی؛ پچھلی ورتی ویندی فہرست (جے ہئی) اڌ ادھوری اپ ڈیٹ تھی ہوئی چھوڑݨ دی بجائے ہٹا ݙتی گئی۔ اڳلی کامیاب ری بلڈ تک ایں لوکیل کیتے کوئی ڈیفالٹ ڈومین سپلیمنٹ نئیں ݙتا ویسی۔','Could not open zip: %s'=>'zip کائنی کھولی ون٘ج سگی: %s','Could not prepare %s for rollback.'=>'%s نوں رول بیک کِیتے تیار نہیں کیتا جا سکیا۔','Could not read %s back after moving it into place.'=>'%s نوں جگہ تے رکھن توں بعد ولدا پڑھیا نہیں جا سکیا۔','Could not read: %s'=>'نہیں پڑھ سکیا: %s','Could not restore the purchase: %s'=>'خریداری بحال کائنی تھی سڳی: %s','Could not show a new restore code: %s'=>'نواں بحالی کوڈ کائنی ݙکھایا ونڄ سڳیا: %s','Could not stage %s'=>'%s سٹیج نہیں تھی سڳی','Could not stage default/%s'=>'default/%s سٹیج نہیں تھی سڳی','Could not start checkout: %s'=>'چیک آؤٹ شروع نہیں تھی سڳیا: %s','Could not verify entry count for %s'=>'%s واسطے اندراجاں دی گنتی دی تصدیق نہیں تھی سڳی','Could not write the downloaded package to disk.'=>'ڈاؤن لوڈ کیتا ہویا پیکیج ڈسک تے نہیں لکھیا ون٘ج سگیا۔','Could not write the staged merged index.'=>'تیار کیتی ہوئی ضم شدہ فہرست لکھی نئیں ونڄ سگی۔','Current translation'=>'موجودہ ترجمہ','Danger zone'=>'خطرے دا علاقہ','Default supplement entry count mismatch.'=>'Default سپلیمنٹ دے اندراجاں دی گنتی نہیں ملدی۔','Delete all Babilim data on uninstall'=>'ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو','Disable Babilim'=>'Babilim غیر فعال کرو','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim غیر فعال کروں؟ انسٹال تھئے ترجمے رہ ویسن، پر اڳوں کوئی چیک یا ڈاؤن لوڈ کائنی تھیسی۔','Don\'t share'=>'Don\'t share','Download'=>'ڈاؤنلوڈ کرو','Downloaded and installed.'=>'ڈاؤن لوڈ تے انسٹال تھی گیا۔','Downloading…'=>'ڈاؤنلوڈ تھیندی پئی اے…','Downloads: %1$d/%2$d (%3$s)'=>'ڈاؤن لوڈ: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ہر کمپوننٹ دا اپݨا حصہ ہر لوکیل دے سانجھے default-domain اضافے وچ۔','Enable Babilim'=>'Babilim فعال کرو','Enabling…'=>'چالو تھی رہیا ہے…','English (United States)'=>'English (United States)','Entries'=>'اندراجات','Entry count mismatch for %s'=>'%s واسطے اندراجاں دی گنتی نہیں ملدی','Error reports'=>'ایرر رپورٹاں','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'ایں سائٹ تے ورتیا ویندا ہر لوکیل (سائٹ لوکیل، انسٹال کیتے ہوئے لینگویج پیک، صارف لوکیلز، تے جیڑھے تساں ہتھوں شامل کرو)۔ کوئی لوکیل کہیں ݙوجھے توں مختلف نئیں سمجھیا ویندا۔','Excluded'=>'خارج','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'ہور ناں یا ایکسٹینشن والیاں فائلاں شامل نہیں ہن، نہ ای uploads، cache، logs، backup، data، vendor، node_modules تے languages فولڈر، چھپیاں ہوئیاں فائلاں، یا اوہ فائلاں جنہاں دے ناں عام رازدار فائلاں نال ملدے ہن (wp-config*، .env*، *.sql، *.log، *.pem، *.key)۔ کوڈ فائلاں وچ ہجے وی اجیہا متن یا ڈیٹا ہو سڳدا ہے جیکوں تusی شیئر نہ کرنا چاہو؛ جے یقین نہ ہووے تاں انہاں کوں چیک کرو۔ سروس آمد تے انہاں ای قسماں دیاں فائلاں کوں دوبارہ ہٹا ݙیندی ہے۔','Free'=>'مفت','Free-plan slots'=>'مفت پلان دے سلاٹ','General'=>'عام','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'جے ایہ آن ہے تاں ان انسٹال کرݨ نال ایں سائٹ دی شناخت وی مٹ ویسی۔ ایں سائٹ نال جڑیا ادا شدہ لائسنس بعد وچ خود بخود بحال کائناں تھی سڳدا؛ اوکوں واپس گھنݨ کیتے تُہاکوں %s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔','Included'=>'شامل','Included in index'=>'فہرست وچ شامل','Install available translations automatically'=>'دستیاب ترجمے آپوں آپ انسٹال کرو','Installed'=>'انسٹال تھیا','Installed translations are kept, but no further checks or downloads will run.'=>'انسٹال کیتے ہوئے ترجمے رکھے ویندے ہن، پر اڳوں کوئی چیک یا ڈاؤن لوڈ نہیں تھیسی۔','Installed · %s'=>'انسٹال تھیا · %s','Installed · built for %1$s, this site has %2$s'=>'انسٹال تھیا ہویا · %1$s کیتے بݨایا ڳیا، ایں سائٹ تے %2$s ہے','Installed · built for %s'=>'انسٹال تھیا ہویا · %s کیتے بݨایا ڳیا','Installed · built for %s, new version failed'=>'انسٹال تھیا · %s کیتے بݨایا ڳیا، نواں ورژن ناکام تھی ڳیا','Installed · built for %s, new version scheduled'=>'انسٹال تھی گیا · %s کیتے بݨایا گیا، نواں ورژن شیڈول کیتا گیا','Installed · built for %s, translating the new version…'=>'انسٹال تھیا ہویا · %s کیتے بݨایا ڳیا، نویں ورژن دا ترجمہ تھیندا پیا ہے…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'انسٹال کیتا ڳیا · %s کیتے بنایا ڳیا؛ ایہ پلگ ان یا تھیم ہݨ سائٹ دے سروس پلان وچ شامل کائنی','Installed · built for a different version'=>'انسٹال تھیا ہویا · ہک ݙوجھے ورژن کیتے بݨایا ڳیا','Installed · built for a different version, new version failed'=>'انسٹال تھیا · کسے ہور ورژن کیتے بݨایا ڳیا، نواں ورژن ناکام تھی ڳیا','Installed · built for a different version, new version scheduled'=>'انسٹال تھی گیا · مختلف ورژن کیتے بݨایا گیا، نواں ورژن شیڈول کیتا گیا','Installed · built for a different version, translating the new version…'=>'انسٹال تھیا ہویا · ہک ݙوجھے ورژن کیتے بݨایا ڳیا، نویں ورژن دا ترجمہ تھیندا پیا ہے…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'انسٹال کیتا ڳیا · کہیں ہور ورژن کیتے بنایا ڳیا؛ ایہ پلگ ان یا تھیم ہݨ سائٹ دے سروس پلان وچ شامل کائنی','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'ایہ سروس دے ہوسٹنگ پرووائیڈر کول محفوظ تھیندا ہے تے ترجمہ بݨاوݨ کیتے AI ماڈلز ایندی پروسیسنگ کریندے ہن۔','Language'=>'زبان','Language:'=>'زبان:','Languages'=>'زباناں','Languages found on this site: %s.'=>'ایں سائٹ تے ملیاں زباناں: %s۔','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'آخری صفائی %1$s تے تھی: %2$d نویں نشان زد کیتیاں گیاں، %3$d فائل مٹائیاں گیاں، %4$d ریکارڈ ہٹائے گئے۔','Maintenance'=>'دیکھ بھال','Maintenance status is not available right now.'=>'دیکھ بھال دی حالت ہݨے دستیاب کائنی۔','Manifest unavailable: %s'=>'مینی فیسٹ دستیاب کائنی: %s','Negation reversed'=>'نفی اُلٹ ڳئی','No'=>'نہیں','No build is available to download for this locale.'=>'ایں لوکیل کیتے ڈاؤن لوڈ کرݨ کیتے کوئی بلڈ دستیاب کائناں۔','No cleanup has run yet.'=>'ہݨ تئیں کوئی صفائی نئیں تھئی۔','No components match these filters. %s'=>'کوئی جزو ایں فلٹراں نال نہیں ملدا۔ %s','No components synced yet.'=>'ہݨ تک کوئی جزو سنک کائنی تھیا۔','No installed translation matches.'=>'کوئی انسٹال کیتا ہویا ترجمہ میل کائناں کھاندا۔','No language is managed yet.'=>'ہݨ تائیں کوئی زبان منیج کائنی تھیندی۔','No pending challenge for this nonce.'=>'اس nonce کِیتے کوئی زیر التوا چیلنج نہیں۔','No pending challenge to verify.'=>'تصدیق کیتے کوئی زیر التوا چیلنج نہیں۔','No plugins or themes found.'=>'کوئی پلگ اِن یا تھیم کینہ لبھی۔','No previous build to roll back to.'=>'رول بیک کرن کِیتے کوئی پچھلی بلڈ نہیں۔','No record for %s'=>'%s واسطے کوئی ریکارڈ کائنی','No site id is on file to rotate a token for.'=>'ٹوکن بدلݨ کیتے کوئی سائٹ آئی ڈی فائل وچ محفوظ نہیں۔','No — component inactive'=>'نہیں — کمپوننٹ غیر فعال ہے','No — component removed'=>'نہیں — کمپوننٹ ہٹا ݙتا ڳیا','No — installed version differs from the active one'=>'نہیں — انسٹال کیتا ہویا ورژن فعال ورژن کنوں مختلف ہے','Not a valid server_build_id: %s'=>'درست server_build_id کائنی: %s','Not covered by the free service plan'=>'مفت سروس پلان وچ شامل کینی','Not installed'=>'انسٹال کینی','Not registered yet'=>'ہݨ تائیں رجسٹر کائنی','Not supported'=>'سپورٹ نئیں کیتا ڳیا','Not verified'=>'تصدیق کائنی تھئی','Note (optional)'=>'نوٹ (اختیاری)','Nothing to choose.'=>'چݨݨ کیتے کجھ کائنی۔','Nothing to confirm.'=>'تصدیق کیتے کجھ کائنی۔','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'پہلے کنوں بند: پلگ ان مٹاوݨ نال ایں سائٹ دی شناخت رکھی ویندی ہے، تاں جو دوبارہ انسٹال کرن تے اوہو ورتی ونڄ سڳے۔','One or more served files no longer match the manifest.'=>'اک یا ودھ فائلاں ہُن مینی فیسٹ نال نہیں ملدیاں۔','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'ایں سائٹ کِیتے اکو واری خریداری: %1$s %2$s۔ ایندے وچ ترجمے دیاں سبھ آوݨ آلیاں اپ ڈیٹس شامل ہن۔ ادائیگی Paddle ولوں نویں ٹیب وچ کیتیویندی ہے۔','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'صرف نیٹ ورک ایڈمنسٹریٹر ایہ کم کر سڳدا ہے، کیوں جو ایہ ترجمے دیاں اوہ فائلاں بدلیندا ہے جیڑھیاں ایں نیٹ ورک دیاں ساریاں سائٹاں وچ سانجھیاں ہن۔','Only plugins and themes can be packaged.'=>'صرف پلگ اِن تے تھیم پیکیج کیتے ونج سکدے ہن۔','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'صرف تݙاں جݙاں تusی کسے ایجھے پلگ ان یا تھیم واسطے اپ لوڈ دی تصدیق کرو جیڑھا WordPress.org تے نہیں ہے: ہر .php تے .js فائل، ہر block.json فائل، تے اس جزو دے مین فولڈر وچ readme.txt، readme.md، style.css تے theme.json، zip دی شکل وچ، عام رازدار فائلاں چھوڑن دے بعد۔','Open Babilim settings'=>'Babilim ترتیباں کھولو','Original language'=>'اصلی زبان','Original string'=>'اصلی سٹرنگ','Paid'=>'ادائیگی والا','Partner'=>'پارٹنر','Please check that your site can be reached from the internet, then try again.'=>'مہربانی کر کے چیک کرو جو تہاݙی سائٹ انٹرنیٹ توں پہنچ وچ ہے، فیر ݙوبارہ کوشش کرو۔','Please choose a category for this report.'=>'مہربانی کر تے ایں رپورٹ کیتے زمرہ چݨو۔','Plugin'=>'پلگ اِن','Plugin · %s'=>'پلگ اِن · %s','Plugins'=>'پلگ اِن','Preview'=>'پیش نظارہ','Purchase restored. This site is now licensed.'=>'خریداری بحال تھی گئی۔ ہݨ اے سائٹ لائسنس یافتہ ہے۔','Re-parsed entry count did not match the built index.'=>'دوبارہ پارس کیتی گئی اندراجات دی گݨتی بݨائے گئے انڈیکس نال میل کائنی کھاندی۔','Re-verify'=>'ݙوبارہ تصدیق کرو','Rebuild index now'=>'ہݨ انڈیکس ݙوبارہ بݨاؤ','Refusing to write outside the Babilim language-file directory.'=>'Babilim دی زبان فائل ڈائریکٹری توں باہر لکھݨ توں انکار۔','Registration response was missing required fields.'=>'رجسٹریشن دے جواب وچ ضروری خانے غائب ہن۔','Registration restarted.'=>'رجسٹریشن ولدا شروع کر ݙتی ڳئی۔','Remove'=>'ہٹاؤ','Remove everything Babilim installed'=>'Babilim دا انسٹال کیتا ہر کجھ ہٹاؤ','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim دا انسٹال کیتا ہر کجھ ہٹاؤ؟ ایہ اس سائٹ تے ہر پلگ اِن تے تھیم کیتے Babilim دیاں انسٹال کیتیاں ہوئیاں ساریاں زبان فائلاں مٹا ݙیسی۔','Remove the %2$s translation of %1$s from this site?'=>'کیا %1$s دا %2$s وچ ترجمہ ایں سائٹ توں ہٹاوݨا اے؟','Removed %d installed component.'=>'%d انسٹال شدہ کمپوننٹ ہٹا ݙتا ڳیا۔' . "\0" . '%d انسٹال شدہ کمپوننٹ ہٹا ݙتے ڳئے۔','Removed after a failed integrity check'=>'سالمیت دی جانچ ناکام تھیݨ دے بعد ہٹا ݙتا گیا','Removed.'=>'ہٹا ݙتا ڳیا۔','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'اس سائٹ تے ہر پلگ اِن تے تھیم کیتے Babilim دیاں انسٹال کیتیاں ہوئیاں ساریاں زبان فائلاں ہٹیندا ہے۔','Report a problem'=>'مسئلے دی رپورٹ کرو','Report translation'=>'ترجمے دی رپورٹ کرو','Request newer translation'=>'نویں ترجمے دی درخواست کرو','Request translation'=>'ترجمے دی درخواست کرو','Requestable'=>'درخواست دے قابل','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'ترجمے دی درخواست کرݨ نال ایہ پلگ اِن یا تھیم اس سائٹ کیتے مفت سروس پلان دے سلاٹس وچوں اک تے آ ویندا ہے (حد تھیمز کیتے %1$d تے پلگ اِنز کیتے %2$d ہے)، جے پہلے توں اک تے نہ ہووے۔ سلاٹ ورتیا ہویا رہندا ہے، تے ناکام ترجمہ اینکوں خالی نہیں کریندا۔','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'ترجمے دی درخواست کرݨ نال ایہ پلگ اِن یا تھیم اس سائٹ کیتے مفت سروس پلان دے سلاٹس وچوں اک تے آ ویندا ہے، جے پہلے توں اک تے نہ ہووے۔ سلاٹ ورتیا ہویا رہندا ہے، تے ناکام ترجمہ اینکوں خالی نہیں کریندا۔','Requesting…'=>'درخواست تھیندی پئی اے…','Restart registration'=>'رجسٹریشن دوبارہ شروع کرو','Restore code'=>'بحالی کوڈ','Restore purchase'=>'خریداری بحال کرو','Retry request'=>'درخواست ولدا کرو','Roll back'=>'پچھلی حالت تے ولو','Roll back and report'=>'پچھلی حالت تے ولو تے رپورٹ کرو','Roll back and send report'=>'پچھلی حالت تے ولو تے رپورٹ بھیجو','Roll back the %2$s translation of %1$s to the previous build?'=>'کیا %1$s دا %2$s وچ ترجمہ پچھلے بلڈ تے واپس کرݨا اے؟','Rolled back and reported.'=>'پچھلے بلڈ تے واپس کر ݙتا ڳیا تے رپورٹ وی بھیج ݙتی ڳئی۔','Rolled back to the previous build.'=>'پچھلے بلڈ تے واپس ونڄ ڳیا۔','Rolled back, but the report could not be sent: %s'=>'واپس ونڄ ڳیا، پر رپورٹ کائنی بھیجی ونڄ سگی: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'رول بیک نال \'%1$s\' (%2$s) اوور رائٹ ہو ویسی، جیڑھی ہُن کسے ہور انسٹال کیتے ہوئے کمپوننٹ (%3$s) کِیتے مہیا کیتی ویندی پئی اے؛ کجھ وی تبدیل نہیں کیتا گیا۔','Rotate-token response was missing site_token.'=>'ٹوکن بدلݨ دے جواب وچ site_token غائب ہئی۔','Save changes'=>'تبدیلیاں محفوظ کرو','Scheduled, waiting to be processed'=>'شیڈول کیتا ڳیا، کارروائی دا انتظار ہے','Search'=>'ڳولو','Search components'=>'جزو تلاش کرو','Search the installed translations'=>'انسٹال کیتے ہوئے ترجمے ڳولو','Select all'=>'سارے چݨو','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'گھٹ جزو چݨو: ہر دور وچ وڈھ توں وڈھ %1$d کارروائیاں ہو سگدیاں ہن (تساں %2$d چݨے ہن)۔','Send report'=>'رپورٹ بھیجو','Service plan'=>'سروس پلان','Settings'=>'ترتیباں','Share error reports'=>'ایرر رپورٹاں شیئر کرو','Share this report'=>'ایہ رپورٹ شیئر کرو','Show a new restore code'=>'نواں بحالی کوڈ ݙکھاؤ','Show the "Report translation" entry in the admin toolbar'=>'ایڈمن ٹول بار وچ "ترجمہ دی رپورٹ کرو" اندراج ڈکھاؤ','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'ایں کمپوننٹ دا کجھ متن ایندے مصنف ہارڈ کوڈ کیتا ہے تے زبان پیک نال ایندا ترجمہ کائنی تھی سڳدا۔','Status'=>'حالت','Status unknown'=>'حالت نامعلوم','String context'=>'سٹرنگ دا سیاق','Suggested translation'=>'تجویز کیتا ہویا ترجمہ','Supplementary translation index'=>'اضافی ترجمیاں دی فہرست','Supplementary translation index rebuilt.'=>'اضافی ترجمیاں دی فہرست ولدا بݨا ݙتی ڳئی۔','Supplementary translation maintenance'=>'اضافی ترجمے دی دیکھ بھال','Supplementary translations'=>'اضافی ترجمے','Sweep aborted without orphaning anything: %s.'=>'کہیں کوں یتیم کیتے بغیر صفائی روک ݙتی گئی: %s۔','Sweep complete: %d file deleted.'=>'سکین مکمل تھی گیا: %d فائل مٹائی ڳئی۔' . "\0" . 'سکین مکمل تھی گیا: %d فائلاں مٹائیاں ڳیاں۔','Sweep now'=>'هݨ سکین کرو','Sync complete.'=>'سنک مکمل تھی ڳیا۔','Thank you. Your report was sent.'=>'شکریہ۔ تہاݙی رپورٹ بھیج ݙتی ڳئی۔','That component is not installed on this site, so a translation cannot be requested for it.'=>'ایہ کمپوننٹ اس سائٹ تے انسٹال کائناں، ایâس کرکے ایندے کیتے ترجمہ دی درخواست نہیں کیتی ونڄ سڳدی۔','That does not look like a restore code.'=>'اے بحالی کوڈ دے طور تے ٹھیک کائنی لگدا۔','That is not a valid WordPress locale code. Nothing was saved.'=>'ایہ WordPress دا درست لوکیل کوڈ کائناں۔ کجھ محفوظ کائناں کیتا ڳیا۔','That is not a valid build identifier.'=>'ایہ درست بلڈ شناخت کار کائنی۔','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'اوہ اپ لوڈ سکرین پرانی ہو گئی ہئی: اوں دے بعد اک ہور اپ لوڈ تیار کیتا گیا ہے۔ کجھ نہیں بھیجیا گیا۔ موجودہ والی ترجمیاں دی لسٹ وچوں ݙیکھو۔','The change could not be recorded in the translation index; please try again.'=>'تبدیلی ترجمیاں دی فہرست وچ درج نہیں ہو سکی؛ مہربانی کر کے ولدا کوشش کرو۔','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'صفائی تھی گئی، پر کجھ تبدیلیاں ترجمیاں دی فہرست وچ درج نئیں تھی سگیاں؛ اڳلی صفائی وچ انہاں کوں درج کرݨ دی ولدا کوشش کیتی ویسی۔','The component has no files that can be uploaded.'=>'اس جزو وچ اپ لوڈ کرن جوڳیاں کوئی فائلاں نہیں ہن۔','The component is not inside the plugins or themes directory.'=>'کمپوننٹ پلگ اِن یا تھیم ڈائریکٹری دے اندر نہیں اے۔','The component\'s main file was not found.'=>'کمپوننٹ دی مین فائل نہیں لبھی۔','The download response was missing a usable location.'=>'ڈاؤن لوڈ دے جواب وچ کوئی قابل استعمال مقام نہیں ہا۔','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'ایہ اندراج اکو پینل کھولدا اے جتھے Babilim دے اس سائیٹ تے انسٹال کیتے ہوئے ترجمے لبھے ونج سڳدے ہن تے اوندے وچوں کہیں دی رپورٹ کیتی ونج سڳدی اے۔','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'خانہ "%1$s" بہوں لمبا ہے: اینکوں %2$d حرف ہن تے حد %3$d ہے۔ کجھ نئیں بھیجیا ڳیا؛ مہربانی کر تے اینکوں چھوٹا کرو تے ول کوشش کرو۔','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'مفت سروس پلان ہر سائٹ کوں پلگ اِنز تے تھیمز کیتے سلاٹس دی محدود گنتی ݙیندا ہے؛ Babilim فعال کرݨ دے بعد ورتے ہوئے سلاٹس ترتیباں وچ ݙکھائے ویندے ہن۔','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'دِتا گیا ڈومین \'%1$s\' نہ تاں پیکیج مینی فیسٹ دے اپنے سلگ \'%2$s\' نال ملدا اے تے نہ ای اوندے text_domain \'%3$s\' نال۔','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' دی ضم شدہ فہرست ولدی بݨائی گئی، پر ترجمیاں دی فہرست اینکوں درج نئیں کر سگی؛ اڳلی ری بلڈ ولدا کوشش کرسی۔','The original text and the translations made from it will be provided to other sites that install the same version.'=>'اصلی متن تے ایندے توں بݨے ترجمے ہوراں سائٹاں کوں مہیا کیتے ویسن جہڑیاں اے ای ورژن انسٹال کریندیاں ہن۔','The package declares no main translation file.'=>'پیکیج وچ کوئی مکھ ترجمے دی فائل ظاہر کائنی کیتی ڳئی۔','The package has no %s for its own text domain.'=>'پیکیج وچ اوندے اپنے ٹیکسٹ ڈومین کِیتے کوئی %s نہیں۔','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'پیکیج مینی فیسٹ دی قسم \'%1$s\' درخواست کیتی قسم \'%2$s\' نال میل نئیں کھاندی۔','The package produced no servable main translation file.'=>'پیکیج کنوں کوئی قابل پیش مکھ ترجمے دی فائل نہیں بݨی۔','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'پیکیج دا ٹیکسٹ ڈومین \'%1$s\' اس سائٹ دی کمپوننٹ دی کاپی (\'%2$s\') نال نہیں ملدا، ایں کِیتے اے انسٹال نہیں کیتا گیا۔','The packaged component could not be read.'=>'پیک کیتا ہویا کمپوننٹ پڑھیا نہیں جا سکیا۔','The registration challenge is not in the expected form.'=>'رجسٹریشن چیلنج متوقع شکل وچ کائنی۔','The report could not be sent.'=>'رپورٹ کائناں بھیجی ونڄ سڳی۔','The search could not be completed.'=>'ڳولݨ مکمل کائناں تھی سڳیا۔','The service asked this site to wait before syncing again.'=>'سروس نے اس سائٹ کوں آکھیا کہ ولدا سنک کرن توں پہلے انتظار کرے۔','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'سروس تُہاݙی سائٹ تائیں نہ پہنچ سگی۔ شاید فائر وال، سکیورٹی پلگ ان یا ہوسٹ دا کوئی اصول درخواست روک ریہا ہے؛ مہربانی کرکے /wp-json/babilim/v1/challenge تے درخواستاں دی اجازت ݙیوو۔','The service\'s upload offer was incomplete.'=>'سروس دی اپ لوڈ پیشکش ادھوری ہئی۔','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'ٹیکسٹ ڈومین \'%1$s\' (%2$s) پہلے ای کسے ہور انسٹال کیتے ہوئے کمپوننٹ (%3$s) کِیتے مہیا کیتا ویندا پیا اے؛ کجھ وی انسٹال نہیں کیتا گیا۔','The upload is kept until you ask Babilim to delete it.'=>'اپ لوڈ تیں تئیں رکھیا ویندا ہے جیں تئیں تساں Babilim کوں اونکوں مٹاوݨ دا نہ آکھو۔','Theme'=>'تھیم','Theme · %s'=>'تھیم · %s','Themes'=>'تھیم','There is no upload in progress.'=>'کوئی اپ لوڈ جاری کائنی۔','There is no upload waiting for confirmation.'=>'کوئی اپ لوڈ تصدیق دا منتظر کائنی۔','These are the languages this site uses. You can change them in %s.'=>'ایہ او زباناں ہن جہڑیاں ایہ سائٹ ورتیندی ہے۔ تساں انہاں کوں %s وچ بدل سگدے ہو۔','These fields will be sent:'=>'ایہ خانے بھیجے ویسن:','This build is not one this site currently knows about for this component/locale.'=>'ایہ بلڈ ایں کمپوننٹ/لوکیل کیتے ایں سائٹ دے معلوم بلڈاں وچ شامل کائناں۔','This component does not declare a version number, so a translation cannot be requested for it.'=>'ایہ کمپوننٹ ورژن نمبر ظاہر کائناں کریندا، ایâس کرکے ایندے کیتے ترجمے دی درخواست نہیں کیتی ونڄ سڳدی۔','This component is larger than the service accepts, so it cannot be uploaded.'=>'اے کمپوننٹ سروس دی قبول کرن دی حد توں وڈا اے، ایں کِیتے اپ لوڈ نہیں ہو سکدا۔','This component was already uploaded. Babilim is checking it now.'=>'ایہ کمپوننٹ پہلے ہی اپ لوڈ تھی ڳیا ہے۔ Babilim ہݨ ایکوں چیک کریندا پئے۔','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'ایں کمپوننٹ دا ورژن نمبر %d حرفاں کنوں ودھ لما ہے، جہڑا Babilim سنبھال کائناں سڳدا، ایâس کرکے ایندے کیتے ترجمے دی درخواست نہیں کیتی ونڄ سڳدی۔','This issues a new restore code and the previous one stops working. Continue?'=>'ایں نال نواں بحالی کوڈ جاری تھیسی تے پچھلا کوڈ کم کرݨ چھوڑ ڈیسی۔ جاری رکھو؟','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'ایں نیٹ ورک وچ سائٹاں ڈھیر ہن، ہک ہک کرکے چیک کائناں کیتیاں ونڄ سڳدیاں، تے کجھ سائٹاں شاید ایں طرح سیٹ ہوون جو پلگ ان مٹاونْ تے اپݨی Babilim شناخت مٹا ݙیون۔ ایجھی سائٹ نال جڑیا ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدا؛ تُہاکوں %s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناختاں رکھݨ کیتے منسوخ دباؤ، ہر سائٹ دیاں Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'اس پلگ ان دا اپنا ورژن، تاں جو جے اے بہوں پرانا ہووے تے سروس تہانکوں اپ ڈیٹ کرݨ دا آکھ سگے۔','This report does not name a valid plugin or theme and locale.'=>'ایں رپورٹ وچ کوئی درست پلگ ان یا تھیم تے لوکیل دا ناں کائناں۔','This report does not name an installed string.'=>'اس رپورٹ وچ کسے انسٹال کیتی ہوئی سٹرنگ دا ناں نہیں ہے۔','This report is missing a valid build to report against.'=>'ایں رپورٹ وچ رپورٹ کرݨ کیتے درست بلڈ موجود کائنی۔','This report will be posted publicly on GitHub and may be kept by third parties.'=>'ایہ رپورٹ GitHub تے عوامی طور تے پوسٹ کیتی ویسی تے تیجی پارٹیاں اینکوں رکھ سڳدیاں ہن۔','This restore code was not recognised for this site.'=>'اے بحالی کوڈ ایں سائٹ کِیتے پچھاتا کائنی گیا۔','This site already has an active registration that can no longer be recovered automatically.'=>'ایں سائٹ دی پہلے کنوں فعال رجسٹریشن موجود ہے جیڑھی ہݨ خودکار طور تے بحال نہیں تھی سڳدی۔','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'اس سائٹ دے %1$d کمپوننٹ %2$d زباناں وچ ہن، جنہاں کِیتے %3$d چیک بیچ چاہیدے ہن؛ Babilim اک رن وچ زیادہ توں زیادہ %4$d سنبھال سکدا اے۔ ترتیباں وچ منیج کیتیاں زباناں گھٹاؤ یا غیر استعمال شدہ پلگ اِن تے تھیم ڈی ایکٹیویٹ کرو، فیر ہُنے ولدا چیک کرو دباؤ۔','This site has no purchase to show a code for.'=>'ایں سائٹ دی کوئی خریداری کائنی جیندا کوڈ ݙکھایا ونڄے۔','This site is already licensed. Reload the page.'=>'ایہ سائٹ پہلے کنوں لائسنس یافتہ ہے۔ ورقہ دوبارہ لوڈ کرو۔','This site is not registered with Babilim yet.'=>'ایہ سائٹ ہݨ تک Babilim نال رجسٹرڈ نہیں ہے۔','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'ایہ سائٹ اوں سائز کولوں وݙی ہے جیڑھا سروس اکو سنک وچ قبول کرین‌دی ہے، ایں کیتے کجھ آئٹم چھوڑ ݙتے ڳئے: %1$d جزو تے %2$d لوکیلز۔','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'ایہ سائٹ ملٹی سائٹ نیٹ ورک دا حصہ ہے، جیڑھا نوے ترجمے خودکار طور تے انسٹال نہیں کریندا۔ جیڑھے ترجمے پہلے کنوں انسٹال ہن اوہ ہݨ وی اپڈیٹ تھیندے ہن۔','This site is verified.'=>'ایں سائٹ دی تصدیق تھی ڳئی ہے۔','This site must be verified first.'=>'پہلے ایں سائٹ دی تصدیق ضروری ہے۔','This site\'s URL, so the service can verify you own it.'=>'اس سائٹ دا URL، تاں جو سروس تصدیق کر سگے جو اے تہاڈی ہے۔','This site\'s address is too long for Babilim to register.'=>'ایں سائٹ دا پتہ Babilim دے رجسٹر کرݨ کیتے بہوں لمبا ہے۔','This site\'s configured locale.'=>'ایں سائٹ دا ترتیب ݙتا ہویا لوکیل۔','This site\'s locale code is not one Babilim can register.'=>'اس سائٹ دا لوکیل کوڈ اوہ نہیں جیڑھا Babilim رجسٹر کر سکے۔','This string can\'t be reported from this site.'=>'ایہ سٹرنگ ایں سائٹ توں رپورٹ کائناں تھی سڳدی۔','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'اے سٹرنگ اس سائٹ تے انسٹال کیتے ہوئے ترجمیاں وچ شامل نہیں ہے۔ دوبارہ تلاش کرو تے لسٹ وچوں اینکوں چنو۔','This translation was updated since you searched. Search again and pick the string from the new list.'=>'تہاڈی تلاش دے بعد اے ترجمہ اپ ڈیٹ تھی گیا ہے۔ دوبارہ تلاش کرو تے نویں لسٹ وچوں سٹرنگ چنو۔','To translate this component, Babilim needs its source.'=>'ایہ کمپوننٹ دا ترجمہ کرݨ کیتے Babilim کوں ایندا سورس چاہیدا ہے۔','Too many attempts. Try again tomorrow.'=>'بہوں کوششاں تھی گیاں۔ کل ولدی کوشش کرو۔','Too many reports today. Try again tomorrow.'=>'اڄ بہوں ساریاں رپورٹاں تھی ڳیاں ہن۔ کل ولدا کوشش کرو۔','Too many requests.'=>'بہوں زیادہ درخواستاں۔','Toolbar'=>'ٹول بار','Translating…'=>'ترجمہ تھیندا پیا ہے…','Translation does not load'=>'ترجمہ لوڈ کائنی تھیندا','Translation failed'=>'ترجمہ ناکام تھی گیا','Translation requested.'=>'ترجمے دی درخواست کر ݙتی ڳئی۔','Translations'=>'ترجمے','Type'=>'قسم','Type at least 2 characters to search.'=>'ڳولݨ کیتے گھٹ توں گھٹ 2 حرف ٹائپ کرو۔','Unexpected HTTP %d response.'=>'غیر متوقع HTTP %d جواب۔','Uninstall'=>'ان انسٹال','Unknown kind: %s'=>'اݨ جاݨی kind: %s','Unsafe domain: %s'=>'غیر محفوظ ڈومین: %s','Unsafe locale: %s'=>'غیر محفوظ لوکیل: %s','Unsafe slug: %s'=>'غیر محفوظ سلگ: %s','Unsafe text_domain: %s'=>'غیر محفوظ text_domain: %s','Update'=>'اپڈیٹ کرو','Update available'=>'اپ ڈیٹ دستیاب ہے','Updates'=>'اپڈیٹاں','Updating…'=>'اپڈیٹ تھیندی پئی اے…','Upgrade this site'=>'ایں سائٹ کوں اپ گریڈ کرو','Upload and request'=>'اپ لوڈ کرو تے درخواست کرو','Upload cancelled.'=>'اپ لوڈ منسوخ کر ݙتا ڳیا۔','Upload complete — translation requested.'=>'اپ لوڈ مکمل تھی ڳیا — ترجمے دی درخواست کر ݙتی ڳئی۔','Upload expired before it finished'=>'اپ لوڈ مکݨ توں پہلے ای ختم تھی گیا','Upload in progress — continue or cancel'=>'اپ لوڈ جاری ہے — جاری رکھو یا منسوخ کرو','Upload this component?'=>'ایہ کمپوننٹ اپ لوڈ کروں؟','Upload was not accepted'=>'اپ لوڈ قبول نئیں تھیا','Uploading'=>'اپ لوڈ تھیندا پئے','Uploading part %1$d of %2$d…'=>'حصہ %1$d از %2$d اپ لوڈ تھیندا پئے…','Uploading…'=>'اپ لوڈ تھیندا پئے…','Verified'=>'تصدیق تھی گئی','Verify response was missing site_token.'=>'تصدیق دے جواب وچ site_token غائب ہئی۔','Version %s'=>'ورژن %s','What is sent when you enable Babilim'=>'Babilim فعال کرݨ تے کیا کجھ بھیجیا ویندا ہے','Where you saw this (optional)'=>'تساں اے کتھاں ݙٹھا (اختیاری)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'جڈاں تئیں ایہ چالو اے، جہڑے ترجمے سروس تہاڈیاں منیجڈ زباناں واسطے دستیاب دسیندی اے اوہ روزانہ دو واری سنک دے دوران انسٹال تھی ویندے ہن۔','WordPress.org'=>'WordPress.org','Wrong for this context'=>'ایں سیاق کیتے غلط','Wrong meaning'=>'غلط مطلب','Wrong plural form'=>'غلط جمع شکل','Wrong term'=>'غلط اصطلاح','Yes'=>'ہاں','You are not allowed to do this.'=>'تہانوں اے کم کرݨ دی اجازت کائنی۔','Your PHP version, for compatibility.'=>'تہاڈا PHP ورژن، موافقت کیتے۔','Your WordPress version, to serve compatible translation files.'=>'تہاڈا WordPress ورژن، تاں جو موافق ترجمہ فائلاں مہیا کیتیاں ونجن۔','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'تہاڈا نواں بحالی کوڈ: %s۔ ایکوں کہیں محفوظ جاہ تے رکھو — پچھلا کوڈ ہݨ کم کائنی کریندا۔','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'تہاݙی رپورٹ AI ماڈلز ولوں خودکار طور تے پروسیس کیتی ویندی ہے تے دوجیاں سائٹاں کیتے ایں ترجمے کوں بہتر بݨا سڳدی ہے۔','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'تُہاݙی سائٹ نے جواب تاں ݙتا، پر متوقع جواب کائناں ہئی۔ ہو سڳدا ہے REST API کہیں ہور پلگ ان نے بدل ݙتی ہووے، یا او اینڈ پوائنٹ کیش تھیا ہووے؛ مہربانی کرکے /wp-json/babilim/v1/challenge کوں کیشنگ تے ری رائٹنگ کنوں الگ رکھو۔','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'تہاݙی سائٹ نے جواب ݙیݨ وچ بہوں دیر لائی۔ مہربانی کر کے بعد وچ ݙوبارہ کوشش کرو، تے چیک کرو جو تہاݙا ہوسٹ بہوں سست یا اوورلوڈ تاں کائنی۔','Zip has no manifest.json.'=>'زپ وچ manifest.json کائنی۔','Zip is missing expected default file: %s'=>'زپ وچ متوقع default فائل گم ہے: %s','Zip is missing expected file: %s'=>'زپ وچ متوقع فائل گم ہے: %s','_manifest.json has an unexpected structure'=>'_manifest.json دا ڈھانچہ غیر متوقع ہے','could not read _manifest.json: %s'=>'_manifest.json نہیں پڑھ سڳے: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest وچ \'%s\' غائب اے یا غلط اے۔','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest دا \'server_build_id\' درست بلڈ آئی ڈی نہیں۔','failed to parse _manifest.json: %s'=>'_manifest.json دا پارس کرݨ ناکام ریہا: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'ایہ %2$d منظم کمپوننٹس وچوں %1$d کوں یتیم کر ݙیسی (اڌ توں ڈھیر)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'ایہ ہر منظم %1$s کمپوننٹ کوں یتیم کر ݙیسی (%2$d وچوں %2$d)','l10n.php entry count mismatch for %s'=>'%s کِیتے l10n.php انٹریاں دی گنتی بے میل','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json وچ \'default_domain_entries\' غلط اے۔','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json وچ \'default_domain_files\' غلط اے۔','manifest.json in the zip is not valid JSON.'=>'زپ وچ manifest.json درست JSON کائنی۔','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json وچ \'%s\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json وچ \'build_no\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json وچ \'entries\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json وچ \'extra_domains\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json وچ \'files\' غائب اے یا غلط اے۔','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json دا \'%s\' متوقع قدر نال میل نئیں کھاندا۔','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json دا \'contract\' درست ورژن سٹرنگ نہیں۔','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json دا \'kind\' لازمی \'plugin\' یا \'theme\' ہووے۔','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json دا \'server_build_id\' درست بلڈ آئی ڈی نہیں۔','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json دا \'status\' لازمی \'published\' ہووے۔','nonce must be a hexadecimal string.'=>'nonce لازمی ہیکساڈیسیمل سٹرنگ ہووے۔','per day'=>'ہر روز','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s کِیتے sha256 بے میل','sha256 mismatch for default/%s'=>'default/%s کِیتے sha256 بے میل','component kind in the sweep brake messageplugin'=>'پلگ ان','component kind in the sweep brake messagetheme'=>'تھیم','problem report categoryOther'=>'ہور','translation statusAvailable'=>'دستیاب','translation statusInstalled'=>'انسٹال تھیا ہویا','Babilim translation turned off.'=>'Babilim ترجمہ بند کر ݙتی گئی۔','Stop using Babilim translation'=>'Babilim ترجمہ دا استعمال بند کرو','Use Babilim translation'=>'Babilim ترجمہ ورتو','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) دا Babilim ترجمہ ورتݨ بند کرݨا ہے؟ WordPress ایندے بجائے تھیم دا اپݨا یا WordPress.org ترجمہ ورتیسی۔ تusی کسے ویلے واپس بدل سکدے ہو۔','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'%1$s (%2$s) دا Babilim ترجمہ ورتݨ بند کرݨا ہے؟ WordPress ایندے بجائے پلگ اِن دا اپݨا یا WordPress.org ترجمہ ورتیسی۔ تusی کسے ویلے واپس بدل سکدے ہو۔','Enjoying Babilim? Please leave a rating on WordPress.org.'=>'کیا تُساں Babilim دا مزہ گھن رہے او؟ مہربانی کرتے WordPress.org تے ریٹنگ ݙیوو۔','Rate Babilim'=>'Babilim کوں ریٹ کرو','Babilim translation bundled with the theme'=>'تھیم دے نال شامل Babilim ترجمہ','Babilim translation bundled with the plugin'=>'پلگ اِن دے نال شامل Babilim ترجمہ','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, the languages it already includes, and which of those bundled translations Babilim generated (language codes only). For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'ہر نصب کیتے ہوئے پلگ اِن تے تھیم لئی: اوندا ناں (سلَگ)، ورژن، text domain، کیا او WordPress.org تے درج ہے، اوندے وچ پہلے کنوں شامل زباناں، تے انہاں شامل ترجمیاں وچوں کیہڑے Babilim بݨائے (صرف زبان کوڈ)۔ ہر نصب کیتے ہوئے Babilim ترجمہ لئی: او کیہڑا ورژن ہے، آخری واری کݙݨ جانچیا گیا، تے کیا او اپݨی فائل جانچ وچ پاس تھیا۔','Working…'=>'کم تھیندا پئے…','Babilim could not finish this. Reload the page and try again.'=>'Babilim ایہ کم مکمل نھیں کر سکیا۔ ورقہ دوبارہ لوڈ کرو تے فیر کوشش کرو۔','This translation does not have the number of forms the language needs.'=>'ایں ترجمے وچ اتنیاں صورتاں کائنی جتنیاں زبان کوں چاہیدیاں ہن۔','This translation is empty.'=>'اے ترجمہ خالی ہے۔','The text has invalid characters or control characters.'=>'متن وچ غلط کریکٹر یا کنٹرول کریکٹر ہن۔','The HTML tags must match the original: same tags, each opened and closed as in the original.'=>'HTML ٹیگ اصل نال میل کھاوݨ چاہیدے ہن: اوہو ٹیگ، ہر اک اصل وانگوں کھولیا تے بند کیتا ہویا۔','The translation has %s, which the original does not. Keep the placeholders of the original; to write a plain percent sign next to a letter, add a space or write %%%%.'=>'ترجمے وچ %s ہے، جیڑھا اصل وچ کائنی۔ اصل دے پلیس ہولڈر رکھو؛ کسی حرف دے نال سادہ پرسنٹ نشان لکھݨ واسطے وقفہ پاؤ یا %%%% لکھو۔','The translation has a lone percent sign that would break the text. Write 100%% for a literal percent sign.'=>'ترجمے وچ اکلا پرسنٹ نشان ہے جیڑھا متن کوں خراب کر ڈیسی۔ سادہ پرسنٹ نشان واسطے 100%% لکھو۔','Unsafe override scope.'=>'غیر محفوظ اوور رائیڈ دا دائرہ۔','The override files could not be written.'=>'اوور رائیڈ فائلاں کائنی لکھیاں ونڄ سڳیاں۔','That plugin, theme, text domain or language is not available here.'=>'اے پلگ ان، تھیم، ٹیکسٹ ڈومین یا زبان ایتھے دستیاب کائنی۔','The editor could not complete that request.'=>'ایڈیٹر اوہ درخواست پوری کائنی کر سڳیا۔','The translation did not pass the checks, so it was not saved. Your text is kept as a draft.'=>'ترجمہ جانچ پڑتال وچوں پاس کائنی تھیا، ایں کر کے محفوظ کائنی کیتا ڳیا۔ تُہاڈا متن مسودے دے طور تے رکھیا ڳیا ہے۔','The table that stores edited translations does not exist yet.'=>'ایڈٹ کیتے ڳئے ترجمے محفوظ کرݨ والا ٹیبل ہݨ تک موجود کائنی۔','That plugin or theme is not installed.'=>'اوہ پلگ اِن یا تھیم انسٹال کائنی۔','That string is not in this translation.'=>'اوہ سٹرنگ ایں ترجمے وچ کائنی۔','The translation could not be saved.'=>'ترجمہ محفوظ کائنی تھی سڳیا۔','Edit translations'=>'ترجمے ایڈٹ کرو','Edit translations: %1$s, %2$s'=>'ترجمے ایڈٹ کرو: %1$s, %2$s','There is nothing to edit yet. Install a plugin or theme, or add a language, and it shows up here.'=>'ہݨ تک ایڈٹ کرݨ کیتے کجھ کائنی۔ کوئی پلگ ان یا تھیم انسٹال کرو، یا کوئی زبان شامل کرو، تاں اے ایتھے ݙکھ ویسی۔','Choose a plugin or theme and a language to edit its translation.'=>'ترجمہ ایڈٹ کرݨ کیتے کوئی پلگ ان یا تھیم تے زبان چݨو۔','Name'=>'ناں','Edit'=>'ایڈٹ کرو','Back to all plugins and themes'=>'سارے پلگ ان تے تھیم ول واپس ونجو','Text domain'=>'ٹیکسٹ ڈومین','Show'=>'ݙکھاؤ','The editor needs JavaScript. Everything else in Babilim works without it.'=>'ایڈیٹر کوں JavaScript دی لوڑ اے۔ Babilim دا باقی سب کجھ اس دے بغیر چلدا اے۔','Untranslated'=>'ترجمہ کیتے بغیر','Needs review'=>'نظرثانی دی لوڑ اے','No longer used'=>'ہݨ استعمال کائنی تھیندا','From Babilim'=>'Babilim کنوں','From WordPress.org'=>'WordPress.org کنوں','From the plugin or theme'=>'پلگ ان یا تھیم کنوں','Save'=>'محفوظ کرو','You are logged out. Log in again in another tab, then press Save.'=>'تساں لاگ آؤٹ تھی ڳئے او۔ کہیں ہور ٹیب وچ ول لاگ اِن کرو، فیر محفوظ کرو دبائو۔','This text is not saved yet. It stays in the field.'=>'اے ٹیکسٹ ہݨ تک محفوظ کائنی تھیا۔ اے خانے وچ ای رہندا اے۔','Form %d'=>'شکل %d','Translation'=>'ترجمہ','Original text'=>'اصلی ٹیکسٹ','Context'=>'سیاق و سباق','Note for translators'=>'ترجمہ کرݨ والیاں کیتے نوٹ','Previous page'=>'پچھلا ورقہ','Next page'=>'اڳلا ورقہ','Page %1$d of %2$d'=>'%2$d وچوں ورقہ %1$d','No more untranslated strings on this page.'=>'اس ورقے تے ہور کوئی ترجمہ کیتے بغیر سٹرنگ کائنی۔','No strings match.'=>'کوئی سٹرنگ میل کائنی کھاندی۔','No strings found. This plugin or theme does not ship a translation template.'=>'کوئی سٹرنگ کائنی لبھی۔ اے پلگ اِن یا تھیم ترجمے دا سانچہ نال کائنی ڈیندا۔','The translation file could not be written yet. It is tried again automatically every day.'=>'ترجمے دی فائل ہݨ تک لکھی کائنی ڳئی۔ ہر روز آپݨے آپ دوبارہ کوشش کیتی ویندی ہے۔','Edit this text'=>'اے ٹیکسٹ ایڈٹ کرو','Has problems'=>'مسئلے ہن','%d string'=>'%d سٹرنگ' . "\0" . '%d سٹرنگاں','%d untranslated'=>'%d ترجمے توں بغیر' . "\0" . '%d ترجمے توں بغیر','%d edited by you'=>'%d تُہاڈے ولوں ایڈٹ کیتے ہوئے' . "\0" . '%d تُہاڈے ولوں ایڈٹ کیتے ہوئے','%d change is live.'=>'%d تبدیلی لائیو ہے۔' . "\0" . '%d تبدیلیاں لائیو ہن۔','%d change is saved.'=>'%d تبدیلی محفوظ تھی گئی ہے۔' . "\0" . '%d تبدیلیاں محفوظ تھی گئیاں ہن۔','%d draft needs fixing and was not saved.'=>'%d مسودے کوں درست کرݨ دی لوڑ ہے تے محفوظ کائناں تھیا۔' . "\0" . '%d مسوداں کوں درست کرݨ دی لوڑ ہے تے محفوظ کائناں تھئے۔','%d change could not be saved.'=>'%d تبدیلی محفوظ کائناں تھی سڳی۔' . "\0" . '%d تبدیلیاں محفوظ کائناں تھی سڳیاں۔','Nothing to save.'=>'محفوظ کرݨ کیتے کجھ کائنی۔','Save %d change'=>'%d تبدیلی محفوظ کرو' . "\0" . '%d تبدیلیاں محفوظ کرو','%d draft saved, not live yet'=>'%d مسودہ محفوظ تھیا، ہجے لائیو کائنی' . "\0" . '%d مسوداں محفوظ تھئے، ہجے لائیو کائنی','%d needs fixing and stays a draft'=>'%d کوں درست کرݨ دی لوڑ ہے تے ایہ مسودہ ای رہ ویسی' . "\0" . '%d کوں درست کرݨ دی لوڑ ہے تے ایہ مسوداں ای رہ ویسن','Discard %d draft? Your live translations stay as they are.'=>'%d مسودہ رد کرو؟ تہاڈے لائیو ترجمے جیویں ہن تیویں رہسن۔' . "\0" . '%d مسوداں رد کرو؟ تہاڈے لائیو ترجمے جیویں ہن تیویں رہسن۔','%s (theme)'=>'%s (تھیم)','Plugin or theme'=>'پلگ اِن یا تھیم','Discard drafts…'=>'مسوداں رد کرو…','Show strings'=>'سٹرنگز وکھاؤ','Text, context, notes or file name'=>'ٹیکسٹ، سیاق، نوٹس یا فائل دا ناں','Searches the original text, the translation, the context, notes for translators and the file the string comes from.'=>'اصلی ٹیکسٹ، ترجمہ، سیاق، مترجمیں واسطے نوٹس تے اوہ فائل جتھوں سٹرنگ آئی اے، ایہناں وچ لبھدا اے۔','Sort'=>'ترتیب','Default'=>'ڈیفالٹ','Untranslated first'=>'غیر ترجمہ شدہ پہلے','Recently edited'=>'حال ہی وچ ایڈٹ کیتے ہوئے','A–Z'=>'A–Z','Source'=>'ذریعہ','All sources'=>'سارے ذرائع','Original'=>'اصلی','Edit the selected string'=>'چݨی ہوئی سٹرنگ ایڈٹ کرو','Details and history'=>'تفصیلاں تے تاریخ','Edited by you'=>'تُہاڈے ولوں ایڈٹ کیتا ہویا','Form %1$d: %2$s'=>'شکل %1$d: %2$s','Translation (%s)'=>'ترجمہ (%s)','This language uses one form for every number.'=>'ایہ زبان ہر عدد واسطے اِکو شکل ورتدی اے۔','Plural forms'=>'جمع شکلاں','empty'=>'خالی','problem'=>'مسئلہ','Original (singular)'=>'اصلی (واحد)','Original (plural)'=>'اصلی (جمع)','Copy original'=>'اصلی کاپی کرو','Details'=>'تفصیلاں','History'=>'تاریخ','WordPress.org language pack'=>'WordPress.org زبان پیک','Bundled with the plugin or theme'=>'پلگ اِن یا تھیم دے نال شامل کیتا ہویا','Yours (edited by you)'=>'تُہاڈا (تُہاڈے ولوں ایڈٹ کیتا ہویا)','Found in'=>'اتھے لبھیا گیا','Restore'=>'بحال کرو','Live'=>'لائیو','Draft'=>'مسودہ','Draft · Problem'=>'مسودہ · مسئلہ','Bundled'=>'شامل کیتا ہویا','Yours'=>'تُہاڈا','(plural)'=>'(جمع)','Discard this draft'=>'ایہ مسودہ رد کرو','Drafts discarded.'=>'مسوداں رد کر ݙتے گئے۔','Draft discarded.'=>'مسودہ رد کر ݙتا گیا۔','This draft is kept, but it does not go live with Save until it is fixed. Your other changes still go live.'=>'ایہ مسودہ رکھیا گیا ہے، پر جݙاں تکر ایہ ٹھیک نہیں تھیندا، محفوظ کرنڑ نال لائیو نہیں تھیسی۔ تُہاڈیاں باقی تبدیلیاں پھیر وی لائیو تھی ویسن۔','Draft saved at %s. Not live yet.'=>'مسودہ %s تے محفوظ کیتا گیا۔ ہجے لائیو نہیں۔','Visitors still see the live text until you press Save.'=>'جݙاں تکر تُسیں محفوظ کرو دبیندے نہیں، وزیٹر لائیو متن ای ݙیکھسن۔','Live now: %1$s (%2$s)'=>'ہݨ لائیو: %1$s (%2$s)','Ctrl'=>'Ctrl','Enter'=>'Enter','next string'=>'اڳلی سٹرنگ','previous / next'=>'پچھلی / اڳلی','copy original'=>'اصلی کاپی کرو','clear'=>'صاف کرو','Open'=>'کھولو','Babilim – Auto Translation & Language Packs'=>'Babilim – آپݨے آپ ترجمہ تے زبان پیک','Auto-translate every plugin and theme on your site, then fine-tune any line in a fast built-in editor. Your edits survive updates.'=>'آپݨی سائٹ دے ہر پلگ اِن تے تھیم دا آپݨے آپ ترجمہ کرو، فیر کسے وی سطر نوں تیز بلٹ اِن ایڈیٹر وچ ٹھیک کرو۔ تُہاڈیاں ایڈٹاں اپڈیٹاں توں بعد وی رہندیاں ہن۔','%d change to review'=>'%d تبدیلی جائزے واسطے' . "\0" . '%d تبدیلیاں جائزے واسطے','No translation yet'=>'ہݨ تک کوئی ترجمہ نئیں','The original text changed in %1$s %2$s.'=>'%1$s %2$s وچ اصلی متن بدل ڳیا ہے۔','Your translation was written for the old text, so the site no longer shows it. Choose what to use for the new text.'=>'تُہاڈا ترجمہ پرانے متن واسطے لکھیا ڳیا ہئی، ایں کیتے سائٹ ہݨ اینکوں نہیں ݙکھیندی۔ چنو جو نویں متن واسطے کیا ورتݨا ہے۔','Old original'=>'پرانا اصلی','New original'=>'نواں اصلی','Your translation (for the old text)'=>'تُہاڈا ترجمہ (پرانے متن واسطے)','Your current translation'=>'تُہاڈا موجودہ ترجمہ','Use my text'=>'میرا متن ورتو','New translation from %s'=>'%s ولوں نواں ترجمہ','Use the new translation'=>'نواں ترجمہ ورتو','Keep my current translation'=>'میرا موجودہ ترجمہ رکھو','Discard my text'=>'میرا متن رد کرو','Whichever you choose becomes a draft and goes live with Save, like any other change.'=>'جیڑھا وی تُسیں چنو، او مسودہ بݨ ویسی تے ہور کہیں تبدیلی وانگوں محفوظ کرنڑ نال لائیو تھی ویسی۔','Or edit it yourself'=>'یا اینکوں آپ ایڈٹ کرو','This text is no longer used: %1$s %2$s does not have this string any more.'=>'ایہ متن ہݨ ورتیا نہیں ویندا: %1$s %2$s وچ ہݨ ایہ سٹرنگ کائنی۔','Delete…'=>'مٹاؤ…','Delete your translation of this text? It is not shown anywhere on the site.'=>'کیا ایں متن دا تُہاڈا ترجمہ مٹاؤں؟ ایہ سائٹ تے کہیں جاہ نہیں ݙکھیندا۔','Translation deleted.'=>'ترجمہ مٹا ݙتا ڳیا۔','That text is still in use, so it cannot be removed here.'=>'ایہ متن ہݨ تک ورتوں وچ ہے، اس کیتے ایکوں ایتھوں ہٹایا نہیں ونڄ سڳدا۔','%1$s – %2$s'=>'%1$s – %2$s','Removed text:'=>'ہٹایا گیا متن:','Added text:'=>'شامل کیتا گیا متن:','When something fails inside Babilim, send an error report to the Babilim service: what failed, where and when, a random report ID, the versions and the site language. Only the error, where it happened and the versions are published as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'جدوں Babilim دے اندر کجھ ناکام ہووے، تاں Babilim سروس نوں اک غلطی دی رپورٹ بھیجو: کیہ ناکام ہویا، کتھے تے کدوں، اک بے ترتیب رپورٹ آئی ڈی، ورژن تے سائٹ دی زبان۔ صرف غلطی، اوہ کتھے ہوئی تے ورژن GitHub تے عوامی مسئلہ دے طور تے شائع کیتے جاندے ہن؛ عوامی مسئلے وچ سائٹ دا پتہ، مواد یا فائل دے راستے شامل نہیں ہوندے۔ ڈیفالٹ طور تے بند ہے۔','Translation edits'=>'ترجمے دی تبدیلیاں','Share my edits with Babilim'=>'میڈیاں تبدیلیاں Babilim نال شیئر کرو','When you change a translation that came from Babilim, your version is sent with the original text, Babilim\'s translation, the plugin or theme, the language and the build. Babilim processes it with AI models and may use it to improve that translation for every site. Off by default.'=>'جدوں تُسیں Babilim ولوں آیا ہویا کوئی ترجمہ بدلدے او، تاں تُہاڈا ورژن اصل متن، Babilim دے ترجمے، پلگ اِن یا تھیم، زبان تے بلڈ نال بھیجیا جاندا ہے۔ Babilim اینوں AI ماڈلز نال پروسیس کردا ہے تے ہو سکدا ہے اینوں ہر سائٹ لئی اوس ترجمے نوں بہتر بنان واسطے ورتے۔ ڈیفالٹ طور تے بند ہے۔','Your own translations'=>'تُہاڈے اپنے ترجمے','Keep my translations when removing everything or uninstalling Babilim.'=>'سبھ کجھ ہٹاون یا Babilim ان انسٹال کرن ویلے میرے ترجمے رکھو۔','Your edits and the files you put in %s always take priority over Babilim\'s. Unchecking this deletes them when you remove everything or uninstall.'=>'تُہاڈیاں تبدیلیاں تے جیہڑیاں فائلاں تُسیں %s وچ رکھدے او اوہ ہمیشہ Babilim دیاں فائلاں توں ودھ ترجیح رکھدیاں ہن۔ اینوں اَن چیک کرن نال سبھ کجھ ہٹاون یا ان انسٹال کرن ویلے اوہ مٹ جان گیاں۔','Files: %s.'=>'فائلاں: %s۔','Imported: %s.'=>'درآمد کیتیاں: %s۔','Already identical: %s.'=>'پہلے ای اکو جیہا: %s۔','Kept your existing translation: %s.'=>'تُہاڈا موجودہ ترجمہ رکھ گھدا گیا: %s۔','Imported, but no longer used in this version: %s.'=>'درآمد کیتیاں گیاں، پر ہُݨ اس ورژن وچ ورتیاں نہیں جاندیاں: %s۔','Kept as drafts to fix: %s.'=>'درست کرن لئی مسودے دے طور تے رکھے گئے: %s۔','Skipped: %s.'=>'چھڈ دتے گئے: %s۔','Review the import'=>'درآمد دا جائزہ گھنو','Loco Translate\'s files are not changed. Deactivate Loco Translate yourself when you are ready.'=>'Loco Translate دیاں فائلاں نہیں بدلیاں جاندیاں۔ جدوں تُسیں تیار ہووو، Loco Translate آپ ڈی ایکٹیویٹ کرو۔','Import from Loco Translate'=>'Loco Translate کنوں درآمد کرو','Found %s Loco Translate file you can import.'=>'%s Loco Translate فائل ملی جیہڑی تُسیں درآمد کر سکدے او۔' . "\0" . '%s Loco Translate فائلاں ملیاں جیہڑیاں تُسیں درآمد کر سکدے او۔','Get the text list from Babilim'=>'Babilim کنوں متن دی فہرست گھنو','Sends the plugin\'s or theme\'s name and version to Babilim.'=>'پلگ اِن یا تھیم دا ناں تے ورژن Babilim نوں بھیجدا ہے۔','Babilim is preparing the list. This takes a few minutes.'=>'Babilim فہرست تیار کر رہیا ہے۔ اس وچ کجھ منٹ لگدے ہن۔','Enable Babilim to get the text list for this plugin or theme.'=>'اس پلگ اِن یا تھیم دی متن دی فہرست گھنݨ لئی Babilim چالو کرو۔','Babilim cannot list the text of this plugin or theme: it is not on WordPress.org and it ships no translation template.'=>'Babilim اس پلگ اِن یا تھیم دا متن نہیں گنوا سکدا: ایہ WordPress.org تے نہیں ہے تے اس نال کوئی ترجمے دا سانچہ نہیں آؤندا۔','Babilim found no translatable text in this version.'=>'Babilim نوں اس ورژن وچ ترجمے دے قابل کوئی متن نہیں لبھیا۔','The editor session has expired.'=>'ایڈیٹر سیشن دی میعاد ختم ہو گئی ہے۔','That plugin or theme is not available here.'=>'اوہ پلگ اِن یا تھیم ایتھے دستیاب نہیں ہے۔','Some Loco Translate files could not be read.'=>'کجھ Loco Translate فائلاں پڑھیاں نہیں جا سکیاں۔','This plugin or theme is not on WordPress.org.'=>'ایہ پلگ اِن یا تھیم WordPress.org تے نہیں ہے۔','Babilim returned an invalid text list.'=>'Babilim نے غلط متن دی فہرست واپس کیتی۔','The text list could not be saved.'=>'متن دی فہرست محفوظ نہیں کیتی جا سکی۔']];